ALTER POLICY damaged_items_select_auth ON public.damaged_items USING (public.security_supply_menu_access(ARRAY['armazem_itens_avariados']));
ALTER POLICY "Authenticated can view unit products" ON public.unit_products USING (public.security_supply_menu_access(ARRAY['armazem_cliente','armazem_transporte','armazem_expedicao','armazem_estoque_myio','armazem_tecnico','armazem_itens_avariados','armazem_checar_qr']));
ALTER POLICY "Authenticated can insert unit products" ON public.unit_products WITH CHECK (created_by=auth.uid() AND public.security_supply_menu_access(ARRAY['armazem_cliente','armazem_transporte','armazem_expedicao','armazem_tecnico','armazem_itens_avariados']));
ALTER POLICY "Authenticated can update unit products" ON public.unit_products USING (public.security_supply_menu_access(ARRAY['armazem_cliente','armazem_transporte','armazem_expedicao','armazem_tecnico','armazem_itens_avariados'])) WITH CHECK (public.security_supply_menu_access(ARRAY['armazem_cliente','armazem_transporte','armazem_expedicao','armazem_tecnico','armazem_itens_avariados']));
ALTER POLICY assembly_release_items_select_auth ON public.assembly_release_items USING (public.security_supply_menu_access(ARRAY['armazem_fabrica','armazem_homologacao','armazem_estoque_myio','armazem_checar_qr']));
ALTER POLICY issues_select_auth ON public.assembly_release_issues USING (public.security_supply_menu_access(ARRAY['armazem_fabrica','armazem_homologacao','armazem_estoque_myio','armazem_checar_qr']));
ALTER POLICY homologation_units_select_auth ON public.homologation_units USING (public.security_app_access(ARRAY['supply']));
ALTER POLICY "Site Survey authenticated users can read material decisions" ON public.site_survey_material_decisions USING (public.can_view_site_survey_visit(visit_id,auth.uid()));
ALTER POLICY "Site Survey authenticated users can update material decisions" ON public.site_survey_material_decisions USING (public.can_view_site_survey_visit(visit_id,auth.uid()) AND (public.has_site_survey_permission(auth.uid(),'site_survey_executar') OR public.has_site_survey_permission(auth.uid(),'site_survey_editar'))) WITH CHECK (public.can_view_site_survey_visit(visit_id,auth.uid()) AND (public.has_site_survey_permission(auth.uid(),'site_survey_executar') OR public.has_site_survey_permission(auth.uid(),'site_survey_editar')));
ALTER POLICY "Authorized users can read order attachments" ON storage.objects USING (bucket_id='order-attachments' AND (owner_id=auth.uid()::text OR (public.security_app_access(ARRAY['supply','cash_flow']) AND (EXISTS (SELECT 1 FROM public.purchase_orders p WHERE p.id::text=(storage.foldername(objects.name))[1]) OR ((storage.foldername(objects.name))[1]='imports' AND EXISTS (SELECT 1 FROM public.import_batches b WHERE b.id::text=(storage.foldername(objects.name))[2]))))));
ALTER POLICY "assembly photos read" ON storage.objects USING (bucket_id='assembly-photos' AND (owner_id=auth.uid()::text OR (public.security_supply_menu_access(ARRAY['armazem_fabrica','armazem_homologacao','armazem_estoque_myio','armazem_checar_qr']) AND EXISTS (SELECT 1 FROM public.assembly_releases r WHERE r.photo_url=objects.name))));